function form_value(string $key, string $default = ''): string { return trim((string) ($_POST[$key] ?? $default)); }
function form_number(string $key): float { return (float) str_replace(',', '.', (string) ($_POST[$key] ?? 0)); }
function form_active(): int { return isset($_POST['is_active']) ? 1 : 0; }
function slug_name(string $value): string { $value = strtr(mb_strtolower($value, 'UTF-8'), ['ç'=>'c','ğ'=>'g','ı'=>'i','ö'=>'o','ş'=>'s','ü'=>'u']); return trim((string) preg_replace('/[^a-z0-9]+/', '-', $value), '-') ?: 'pelish-'.date('YmdHis'); }
function redirect_page(string $page, array $query = []): never { header('Location: '.admin_url($page, $query)); exit; }
function option_list(array $values, string $selected = ''): void { foreach ($values as $key => $value) { $optionValue = is_string($key) ? $key : (string) $value; ?><option value="<?= e($optionValue) ?>" <?= $optionValue === $selected ? 'selected' : '' ?>><?= e((string) $value) ?></option><?php } }
function confirm_button(string $action, int $id, string $message, array $extra = []): void { ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=e($action)?>"><input type="hidden" name="id" value="<?=$id?>"><?php foreach($extra as $name=>$value):?><input type="hidden" name="<?=e($name)?>" value="<?=e((string)$value)?>"><?php endforeach?><button class="danger-button" data-confirm="<?=e($message)?>" title="Sil"><i class="fa-solid fa-trash"></i></button></form><?php }
