    }
    if ($action==='delete-customer'||$action==='toggle-customer'){$pdo->prepare($action==='delete-customer'?'DELETE FROM pelish_customers WHERE id=?':'UPDATE pelish_customers SET is_active=IF(is_active=1,0,1) WHERE id=?')->execute([(int)$_POST['id']]);admin_flash('success',$action==='delete-customer'?'Müşteri silindi.':'Müşteri durumu güncellendi.');redirect_page('customers');}
    if ($action === 'save-marketplace') {
