function dashboard(PDO $pdo): void {
  $m=$pdo->query("SELECT (SELECT COUNT(*) FROM pelish_products WHERE is_active=1) products,(SELECT COUNT(*) FROM pelish_orders WHERE DATE(created_at)=CURDATE()) orders,(SELECT COALESCE(SUM(grand_total),0) FROM pelish_orders WHERE DATE(created_at)=CURDATE() AND status<>'İptal') revenue,(SELECT COUNT(*) FROM pelish_customers) customers")->fetch();$recent=$pdo->query('SELECT o.*,CONCAT(c.first_name," ",c.last_name) customer FROM pelish_orders o LEFT JOIN pelish_customers c ON c.id=o.customer_id ORDER BY o.id DESC LIMIT 6')->fetchAll();$low=$pdo->query('SELECT * FROM pelish_products WHERE stock<=5 ORDER BY stock LIMIT 6')->fetchAll();
  panel_header('dashboard','Ana Sayfa',[['label'=>'Genel Bakış','href'=>admin_url('dashboard'),'active'=>true],['label'=>'Hızlı İşlemler','href'=>'#quick']]);?>
  <section class="licence-card"><div class="licence-icon"><i class="fa-solid fa-sparkles"></i></div><div><strong>Hoş geldin, Pelish.</strong><p>Mağazanın günlük özetini, siparişlerini ve stok hareketlerini buradan takip edebilirsin.</p></div><a href="<?=admin_url('orders',['new'=>1])?>"><i class="fa-solid fa-plus"></i> Yeni Sipariş</a></section>
  <section class="stat-grid dashboard-stats"><article><span>AKTİF ÜRÜNLER</span><strong><?= (int)$m['products']?></strong><i class="fa-solid fa-boxes-stacked"></i></article><article><span>BUGÜN SİPARİŞ</span><strong><?= (int)$m['orders']?></strong><i class="fa-solid fa-bag-shopping"></i></article><article><span>BUGÜN CİRO</span><strong><?=admin_money((float)$m['revenue'])?></strong><i class="fa-solid fa-chart-line"></i></article><article><span>TOPLAM MÜŞTERİ</span><strong><?= (int)$m['customers']?></strong><i class="fa-solid fa-users"></i></article></section>
  <section class="dashboard-grid" id="quick"><article class="table-card"><div class="table-title"><div><span>SİPARİŞLER</span><h1>Son siparişler</h1></div><a class="button ghost" href="<?=admin_url('orders')?>">Tümü</a></div><div class="compact-list"><?php foreach($recent as $o):?><a class="compact-row" href="<?=admin_url('orders',['edit'=>$o['id']])?>"><span class="list-icon"><i class="fa-solid fa-receipt"></i></span><span><strong><?=e($o['order_number'])?></strong><small><?=e($o['customer']?:'Misafir müşteri')?></small></span><b><?=admin_money((float)$o['grand_total'])?></b><em class="pill <?=e(slug_name($o['status']))?>"><?=e($o['status'])?></em></a><?php endforeach;if(!$recent):?><div class="empty-state"><i class="fa-solid fa-bag-shopping"></i><strong>Henüz sipariş yok.</strong></div><?php endif?></div></article><article class="table-card"><div class="table-title"><div><span>STOK UYARISI</span><h1>Azalan stoklar</h1></div><a class="button ghost" href="<?=admin_url('products')?>">Ürünler</a></div><div class="compact-list"><?php foreach($low as $p):?><a class="compact-row" href="<?=admin_url('products',['edit'=>$p['id']])?>"><span class="list-icon muted"><i class="fa-solid fa-box"></i></span><span><strong><?=e($p['name'])?></strong><small><?=e($p['sku'])?></small></span><b class="<?=!$p['stock']?'negative':''?>"><?= (int)$p['stock']?> adet</b></a><?php endforeach;if(!$low):?><div class="empty-state"><i class="fa-solid fa-circle-check"></i><strong>Stok seviyesi güvenli.</strong></div><?php endif?></div></article></section>
  <section class="quick-action-grid"><a href="<?=admin_url('products',['new'=>1])?>"><i class="fa-solid fa-box-open"></i><span>Yeni ürün ekle</span><small>Stok ve fiyat tanımla</small></a><a href="<?=admin_url('customers',['new'=>1])?>"><i class="fa-solid fa-user-plus"></i><span>Müşteri ekle</span><small>Müşteri kartı oluştur</small></a><a href="<?=admin_url('vouchers',['new'=>1])?>"><i class="fa-solid fa-ticket"></i><span>Hediye çeki oluştur</span><small>Kampanya tanımla</small></a><a href="<?=admin_url('reports')?>"><i class="fa-solid fa-chart-pie"></i><span>Raporları incele</span><small>Satış performansını gör</small></a></section><?php panel_footer();
