function products(PDO $pdo): void {
  $q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'all');$where=[];$args=[];if($q!==''){$where[]='(name LIKE ? OR sku LIKE ? OR barcode LIKE ? OR category LIKE ?)';$args=array_fill(0,4,'%'.$q.'%');}if($status==='active')$where[]='is_active=1';if($status==='passive')$where[]='is_active=0';if($status==='stock')$where[]='stock>0';if($status==='out-of-stock')$where[]='stock=0';$st=$pdo->prepare('SELECT * FROM pelish_products'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY id DESC');$st->execute($args);$items=$st->fetchAll();$m=$pdo->query('SELECT COUNT(*) total,SUM(is_active=1) active,COALESCE(SUM(stock),0) stock,SUM(stock=0) empty_stock FROM pelish_products')->fetch();$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM pelish_products WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch()?:null;}$f=$edit?:['id'=>'','name'=>'','category'=>'','sku'=>'','barcode'=>'','image_url'=>'','sale_price'=>'','list_price'=>'','cost_price'=>'','stock'=>0,'desi'=>0,'is_active'=>1];
  panel_header('products','Ürün Yönetimi',[['label'=>'Ürünler','href'=>admin_url('products'),'active'=>true],['label'=>'Kategoriler','href'=>admin_url('catalog',['type'=>'categories'])],['label'=>'Markalar','href'=>admin_url('catalog',['type'=>'brands'])],['label'=>'Etiketler','href'=>admin_url('catalog',['type'=>'tags'])]]);?>
  <section class="licence-card"><div class="licence-icon"><i class="fa-solid fa-store"></i></div><div><strong>Ürün kataloğun hazır.</strong><p>Ürün, stok, fiyat ve yayın görünürlüğünü bu ekrandan doğrudan yönetebilirsin.</p></div><a href="<?=admin_url('products',['new'=>1])?>"><i class="fa-solid fa-plus"></i> Yeni Ürün</a></section><section class="stat-grid"><article><span>TOPLAM ÜRÜN</span><strong><?= (int)$m['total']?></strong><i class="fa-solid fa-boxes-stacked"></i></article><article><span>AKTİF ÜRÜN</span><strong><?= (int)$m['active']?></strong><i class="fa-solid fa-circle-check"></i></article><article><span>TOPLAM STOK</span><strong><?= (int)$m['stock']?></strong><i class="fa-solid fa-cubes"></i></article><article><span>STOKTA YOK</span><strong><?= (int)$m['empty_stock']?></strong><i class="fa-solid fa-triangle-exclamation"></i></article></section>
  <section class="filter-card"><form method="get" class="filters"><input type="hidden" name="page" value="products"><label class="quick-search"><i class="fa-solid fa-magnifying-glass"></i><input name="q" value="<?=e($q)?>" placeholder="Ürün adı, kodu veya barkod ara…"></label><select name="status"><option value="all">Tüm ürünler</option><?php option_list(['active'=>'Aktif ürünler','passive'=>'Pasif ürünler','stock'=>'Stokta olanlar','out-of-stock'=>'Stokta olmayanlar'],$status)?></select><button class="button info"><i class="fa-solid fa-filter"></i> Filtrele</button><a class="button ghost" href="<?=admin_url('products')?>">Temizle</a></form></section>
