function catalog(PDO $pdo): void {
  $type=in_array($_GET['type']??'', ['categories','brands','tags'],true)?$_GET['type']:'categories';$meta=['categories'=>['Kategoriler','Kategori'],'brands'=>['Markalar','Marka'],'tags'=>['Etiketler','Etiket']][$type];$s=$pdo->prepare('SELECT * FROM pelish_catalog_items WHERE type=? ORDER BY name');$s->execute([$type]);$items=$s->fetchAll();$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM pelish_catalog_items WHERE id=? AND type=?');$s->execute([(int)$_GET['edit'],$type]);$edit=$s->fetch()?:null;}$f=$edit?:['id'=>'','name'=>'','slug'=>'','description'=>'','is_active'=>1];panel_header('catalog','Ürün Yönetimi',[['label'=>'Ürünler','href'=>admin_url('products')],['label'=>'Kategoriler','href'=>admin_url('catalog',['type'=>'categories']),'active'=>$type==='categories'],['label'=>'Markalar','href'=>admin_url('catalog',['type'=>'brands']),'active'=>$type==='brands'],['label'=>'Etiketler','href'=>admin_url('catalog',['type'=>'tags']),'active'=>$type==='tags']]);?>
  <section class="licence-card"><div class="licence-icon"><i class="fa-solid fa-folder-tree"></i></div><div><strong><?=e($meta[0])?> yönetimi.</strong><p>Ürün kataloğunda kullanılan <?=mb_strtolower($meta[0],'UTF-8')?> tanımlarını doğrudan yönet.</p></div><a href="<?=admin_url('catalog',['type'=>$type,'new'=>1])?>"><i class="fa-solid fa-plus"></i> Yeni <?=e($meta[1])?></a></section><section class="table-card"><div class="table-title"><div><span>ÜRÜN YÖNETİMİ</span><h1><?=e($meta[0])?></h1></div><a class="button primary" href="<?=admin_url('catalog',['type'=>$type,'new'=>1])?>"><i class="fa-solid fa-plus"></i> Yeni <?=e($meta[1])?></a></div><div class="table-scroll"><table><thead><tr><th>Ad</th><th>Bağlantı adı</th><th>Açıklama</th><th>Durum</th><th>İşlemler</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><strong><?=e($i['name'])?></strong></td><td><code><?=e($i['slug'])?></code></td><td><?=e($i['description']?:'-')?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle-catalog"><input type="hidden" name="id" value="<?=$i['id']?>"><input type="hidden" name="type" value="<?=e($type)?>"><button class="status <?=$i['is_active']?'on':''?>"><i class="fa-regular fa-circle-check"></i> <?=$i['is_active']?'Aktif':'Pasif'?></button></form></td><td><div class="row-actions"><a href="<?=admin_url('catalog',['type'=>$type,'edit'=>$i['id']])?>"><i class="fa-solid fa-pen"></i></a><?php confirm_button('delete-catalog',(int)$i['id'],'Bu kayıt silinsin mi?',['type'=>$type])?></div></td></tr><?php endforeach?></tbody></table></div></section>
  <?php ob_start();?><form method="post" class="product-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save-catalog"><input type="hidden" name="id" value="<?=$f['id']?>"><input type="hidden" name="type" value="<?=e($type)?>"><div class="form-grid"><label>Ad<input required name="name" value="<?=e($f['name'])?>"></label><label>Bağlantı adı<input name="slug" value="<?=e($f['slug'])?>"></label><label class="wide">Açıklama<textarea name="description"><?=e($f['description'])?></textarea></label><label class="switch-line"><input type="checkbox" name="is_active" <?=$f['is_active']?'checked':''?>> Aktif</label></div><div class="modal-actions"><a href="<?=admin_url('catalog',['type'=>$type])?>" class="button ghost">İptal</a><button class="button primary">Kaydet</button></div></form><?php modal('catalog','ÜRÜN YÖNETİMİ',$edit?'Kaydı düzenle':'Yeni '.$meta[1],ob_get_clean());panel_footer();
}

function reports(PDO $pdo): void {
  $m=$pdo->query("SELECT COUNT(*) orders,COALESCE(SUM(CASE WHEN status<>'İptal' THEN grand_total ELSE 0 END),0) revenue,COALESCE(AVG(CASE WHEN status<>'İptal' THEN grand_total END),0) average_basket,SUM(status='İptal') cancelled FROM pelish_orders")->fetch();$statuses=$pdo->query('SELECT status,COUNT(*) count,COALESCE(SUM(grand_total),0) total FROM pelish_orders GROUP BY status ORDER BY count DESC')->fetchAll();$products=$pdo->query('SELECT product_name,SUM(quantity) qty,SUM(quantity*unit_price) total FROM pelish_order_items GROUP BY product_name ORDER BY qty DESC LIMIT 6')->fetchAll();$customers=$pdo->query('SELECT CONCAT(c.first_name," ",c.last_name) name,COUNT(o.id) count,COALESCE(SUM(o.grand_total),0) total FROM pelish_customers c LEFT JOIN pelish_orders o ON o.customer_id=c.id GROUP BY c.id ORDER BY total DESC LIMIT 6')->fetchAll();$max=max(array_map(static fn($x)=>(int)$x['count'],$statuses)?:[1]);panel_header('reports','Raporlar',[['label'=>'Genel Bakış','href'=>admin_url('reports'),'active'=>true],['label'=>'Siparişler','href'=>admin_url('orders')],['label'=>'Ürünler','href'=>admin_url('products')]]);?>
  <section class="licence-card"><div class="licence-icon"><i class="fa-solid fa-chart-pie"></i></div><div><strong>Satış performansını izle.</strong><p>Raporlar mevcut sipariş, ürün ve müşteri verilerinden gerçek zamanlı hesaplanır.</p></div><a href="<?=admin_url('orders',['new'=>1])?>"><i class="fa-solid fa-plus"></i> Sipariş Oluştur</a></section><section class="stat-grid"><article><span>TOPLAM CİRO</span><strong><?=admin_money((float)$m['revenue'])?></strong><i class="fa-solid fa-sack-dollar"></i></article><article><span>TOPLAM SİPARİŞ</span><strong><?=$m['orders']?></strong><i class="fa-solid fa-receipt"></i></article><article><span>ORT. SEPET</span><strong><?=admin_money((float)$m['average_basket'])?></strong><i class="fa-solid fa-basket-shopping"></i></article><article><span>İPTAL SİPARİŞ</span><strong><?=$m['cancelled']?></strong><i class="fa-solid fa-ban"></i></article></section><section class="report-grid"><article class="table-card"><div class="table-title"><div><span>SİPARİŞ DAĞILIMI</span><h1>Duruma göre siparişler</h1></div></div><div class="bar-list"><?php foreach($statuses as $s):?><div><div class="bar-label"><span><?=e($s['status'])?></span><strong><?=$s['count']?> sipariş · <?=admin_money((float)$s['total'])?></strong></div><span class="bar"><i style="width:<?=max(5,round($s['count']/$max*100))?>%"></i></span></div><?php endforeach;if(!$statuses):?><div class="empty-state"><i class="fa-solid fa-chart-simple"></i><strong>Rapor için sipariş verisi gerekiyor.</strong></div><?php endif?></div></article><article class="table-card"><div class="table-title"><div><span>ÜRÜN PERFORMANSI</span><h1>En çok satılanlar</h1></div></div><div class="compact-list"><?php foreach($products as $p):?><div class="compact-row"><span class="list-icon"><i class="fa-solid fa-box"></i></span><span><strong><?=e($p['product_name'])?></strong><small><?=$p['qty']?> adet satıldı</small></span><b><?=admin_money((float)$p['total'])?></b></div><?php endforeach?></div></article><article class="table-card report-wide"><div class="table-title"><div><span>MÜŞTERİ ANALİZİ</span><h1>En değerli müşteriler</h1></div></div><div class="table-scroll"><table><thead><tr><th>Müşteri</th><th>Sipariş Sayısı</th><th>Toplam Harcama</th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td><strong><?=e($c['name'])?></strong></td><td><?=$c['count']?></td><td><strong><?=admin_money((float)$c['total'])?></strong></td></tr><?php endforeach?></tbody></table></div></article></section><?php panel_footer();
}

match($page){'products'=>products($pdo),'orders'=>orders($pdo),'marketplaces'=>marketplaces($pdo),'vouchers'=>vouchers($pdo),'customers'=>customers($pdo),'catalog'=>catalog($pdo),'reports'=>reports($pdo),default=>dashboard($pdo)};
